      "#include <future>\n#include <iostream>\n#include <stdexcept>\nint square(int x) {\n    if (x < 0) throw std::invalid_argument(\"negative input\");\n    return x * x;\n}\nint main() {\n    auto result = std::async(std::launch::async, square, 7);\n    try { std::cout << result.get() << '\\n'; }\n    catch (const std::invalid_argument& e) { std::cerr << e.what() << '\\n'; }\n}",
