      "#include <iostream>\n#include <mutex>\n#include <thread>\nstruct Account { int balance; std::mutex m; };\nvoid send(Account& from, Account& to) {\n    std::scoped_lock lock(from.m, to.m);\n    --from.balance; ++to.balance;\n}\nint main() {\n    Account a{1000, {}}, b{1000, {}};\n    std::thread x([&] { for (int i=0;i<100;++i) send(a,b); });\n    std::thread y([&] { for (int i=0;i<30;++i) send(b,a); });\n    x.join(); y.join();\n    std::cout << a.balance << ' ' << b.balance << '\\n';\n}",
